function renewal_display_date(?string $value, bool $withTime = false): string {
    if (!$value) return 'Belum tersedia';
    $date = date_create_immutable($value);
    return $date ? $date->format($withTime ? 'd/m/Y, H:i' : 'd/m/Y') : $value;
}
function renewal_mail_label(?string $value): string {
    return ['sent'=>'Dihantar','sending'=>'Sedang dihantar','failed'=>'Gagal dihantar'][$value ?? ''] ?? 'Belum dihantar';
}
