<div class="grid"><div><small>Pelan / tempoh</small><strong><?php echo escape_html($r['plan_name']); ?> · 12 bulan</strong></div><div><small>Jumlah pembaharuan</small><strong>RM <?php echo number_format((float)$r['amount'],2); ?></strong></div><div><small>Sebut harga sah sehingga</small><strong><?php echo escape_html(renewal_display_date($r['valid_until'])); ?></strong><?php if($r['valid_until']<date('Y-m-d') && !in_array($r['status'],['paid','cancelled'],true)): ?><small class="danger">Tamat tempoh</small><?php endif; ?></div></div>
<?php if($r['new_expiry']): ?><div class="renewal-success"><span aria-hidden="true">✓</span> Pembaharuan disahkan · Langganan sehingga <strong><?php echo escape_html(renewal_display_date($r['new_expiry'])); ?></strong></div><?php endif; ?>
<div class="row document-links"><a class="button" href="renewal_download.php?id=<?php echo (int)$r['id']; ?>">↓ Sebut harga PDF</a><?php if($r['receipt_path']): ?><a class="button" href="renewal_download.php?id=<?php echo (int)$r['id']; ?>&amp;type=receipt">↓ Resit bayaran</a><?php endif; ?></div>
<?php }